import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadMewarData(){const e=readFileSync(resolve(__dirname,"../../mewar-kingdom-explorer/mewar-data.js"),"utf-8");return new Function(e+"\nreturn { MEWAR_INFO, TIMELINE_DATA, RULERS_DATA, CONTRIBUTIONS_DATA, GALLERY_IMAGES, REFERENCES };")()}describe("Kingdom of Mewar Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadMewarData()}),describe("MEWAR_INFO metadata",()=>{it("contains correct Kingdom of Mewar attributes",()=>{expect(e.MEWAR_INFO.id).toBe("mewar-kingdom"),expect(e.MEWAR_INFO.name).toContain("Kingdom of Mewar"),expect(e.MEWAR_INFO.dynasty).toContain("Sisodia"),expect(e.MEWAR_INFO.period).toContain("728")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.MEWAR_INFO.quickStats)).toBe(!0),expect(e.MEWAR_INFO.quickStats.length).toBe(6)})}),describe("TIMELINE_DATA & RULERS_DATA",()=>{it("contains milestone timeline items and key rulers including Maharana Pratap",()=>{expect(Array.isArray(e.TIMELINE_DATA)).toBe(!0),expect(e.TIMELINE_DATA.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.RULERS_DATA)).toBe(!0),expect(e.RULERS_DATA.length).toBeGreaterThanOrEqual(4)})}),describe("CONTRIBUTIONS_DATA",()=>{it("contains required contribution fields",()=>{expect(e.CONTRIBUTIONS_DATA.overview).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.fortsAndPalaces).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.waterEngineering).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.vijayStambha).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.rajputResilience).toBeDefined()})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});